const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';
const inboxId = 19;

const results = [];
const items = $input.all();

for (const item of items) {
  try {
    const rawPhone = String(item.json.Teléfono || item.json.Telefono || item.json.phone || '').replace(/\D/g, '');
    const cleanPhone = rawPhone.length > 0 ? (rawPhone.startsWith('+') ? rawPhone : `+${rawPhone}`) : '';
    const name = String(item.json.Nombre || item.json.name || 'Cliente').trim();

    if (!cleanPhone) {
      results.push({ json: { ...item.json, chatwoot_sync: 'skipped_no_phone' } });
      continue;
    }

    let contactId = null;
    try {
      const searchRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `${chatwootBase}/contacts/search?q=${encodeURIComponent(rawPhone)}`,
        headers: { 'api_access_token': chatwootToken },
        json: true
      });
      if (searchRes.payload && searchRes.payload.length > 0) {
        contactId = searchRes.payload[0].id;
      }
    } catch (e) {}

    if (!contactId) {
      try {
        const createRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `${chatwootBase}/contacts`,
          headers: {
            'api_access_token': chatwootToken,
            'Content-Type': 'application/json'
          },
          body: { name, phone_number: cleanPhone },
          json: true
        });
        contactId = createRes.payload?.contact?.id;
      } catch (e) {}
    }

    if (!contactId) {
      results.push({ json: { ...item.json, chatwoot_sync: 'contact_failed' } });
      continue;
    }

    let conversationId = null;
    try {
      const convListRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `${chatwootBase}/contacts/${contactId}/conversations`,
        headers: { 'api_access_token': chatwootToken },
        json: true
      });
      const convs = convListRes.payload || [];
      const match = convs.find(c => Number(c.inbox_id) === inboxId && c.status !== 'resolved') || convs.find(c => Number(c.inbox_id) === inboxId);
      if (match) conversationId = match.id;
    } catch (e) {}

    if (!conversationId) {
      try {
        const createConvRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `${chatwootBase}/conversations`,
          headers: {
            'api_access_token': chatwootToken,
            'Content-Type': 'application/json'
          },
          body: { inbox_id: inboxId, contact_id: contactId },
          json: true
        });
        conversationId = createConvRes.id;
      } catch (e) {}
    }

    if (!conversationId) {
      results.push({ json: { ...item.json, chatwoot_sync: 'conv_failed' } });
      continue;
    }

    const templateText = `*MENSAJE URGENTE*\n\n☀️Buenos días ${name},\n\n📺Tu suscripción a Total TV *VENCE el día de HOY*\n\n💵Te invitamos a renovar tu plan, y seguir disfrutando del Entretenimiento sin Límites!\n\n¡Gracias por preferirnos!`;

    const noteContent = `📌 *Plantilla WhatsApp Enviada (Outbound)*\n• Plantilla: \`vencehoy\` (es)\n• Destinatario: ${cleanPhone}\n• Fecha/Hora: ${new Date().toLocaleString('es-VE', { timeZone: 'America/Caracas' })}\n\n📝 *Mensaje:*\n${templateText}`;

    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${conversationId}/messages`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: { content: noteContent, private: true },
        json: true
      });
    } catch (e) {}

    results.push({
      json: {
        ...item.json,
        chatwoot_contact_id: contactId,
        chatwoot_conversation_id: conversationId,
        chatwoot_sync: 'success'
      }
    });
  } catch (err) {
    results.push({ json: { ...item.json, chatwoot_sync: 'error', error: err.message } });
  }
}

return results;

